package com.nexodb.ui;

import static com.nexodb.util.I18n.tr;
import com.nexodb.db.*;
import com.nexodb.model.*;
import com.nexodb.util.SqlFiles;
import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.List;
import java.util.function.Supplier;

public final class ScheduledTasksPanel extends JPanel {
    private final ScheduledTasks engine;private final Supplier<List<ConnectionProfile>> profiles;private final String defaultProfile,database;
    private List<ScheduledTasks.Task> tasks=List.of();private final DefaultTableModel model=new DefaultTableModel(new Object[]{tr("Nombre"),tr("Tipo"),tr("Base"),tr("Activa"),tr("Próxima ejecución"),tr("Último resultado"),tr("Archivos")},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
    private final javax.swing.Timer timer=new javax.swing.Timer(2000,e->refresh());
    public ScheduledTasksPanel(ScheduledTasks engine,Supplier<List<ConnectionProfile>> profiles,String defaultProfile,String database){super(new BorderLayout(8,8));this.engine=engine;this.profiles=profiles;this.defaultProfile=defaultProfile;this.database=database;setBorder(new javax.swing.border.EmptyBorder(12,12,12,12));
        JPanel top=new JPanel(new BorderLayout(6,8));top.add(new JLabel(tr("Las tareas se ejecutan mientras AdisDB está abierto. Si el equipo está apagado o suspendido, se reanudan al abrirlo.")),BorderLayout.NORTH);JToolBar bar=new JToolBar();bar.setFloatable(false);
        addAction(bar,"Nuevo reporte",()->edit(null,ScheduledTasks.Kind.REPORT));addAction(bar,"Nuevo respaldo",()->edit(null,ScheduledTasks.Kind.BACKUP));addAction(bar,"Nuevo script SQL",()->edit(null,ScheduledTasks.Kind.SQL));bar.addSeparator();addAction(bar,"Editar",()->{var task=selected();if(task!=null)edit(task,task.kind());});addAction(bar,"Ejecutar ahora",()->{var task=selected();if(task!=null&&JOptionPane.showConfirmDialog(this,task.name()+"\n"+task.database()+"\n"+tr("¿Ejecutar esta tarea ahora?"),tr("Tareas programadas"),JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){engine.runNow(task.id());refresh();}});addAction(bar,"Activar / pausar",()->{var task=selected();if(task!=null)try{engine.enable(task.id(),!task.enabled());refresh();}catch(Exception error){error(error);}});addAction(bar,"Cancelar",()->{var task=selected();if(task!=null)engine.cancel(task.id());});addAction(bar,"Eliminar",()->{var task=selected();if(task!=null&&JOptionPane.showConfirmDialog(this,tr("¿Eliminar la tarea?")+"\n"+task.name(),tr("Tareas programadas"),JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{engine.delete(task.id());refresh();}catch(Exception error){error(error);}});top.add(bar,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);table.setRowHeight(28);add(new JScrollPane(table));add(new JLabel(tr("Si cambia el archivo SQL o la conexión, la tarea se pausa hasta que vuelvas a revisarla. Los reportes se guardan como HTML y CSV.")),BorderLayout.SOUTH);refresh();
    }
    public void addNotify(){super.addNotify();timer.start();}public void removeNotify(){timer.stop();super.removeNotify();}
    public void create(ScheduledTasks.Kind kind){edit(null,kind);}
    private void addAction(JToolBar bar,String text,Runnable action){JButton button=UiLanguage.text(new JButton(tr(text)),UiLanguage.key(text));button.addActionListener(e->{if(Set.of("Activar / pausar","Cancelar").contains(text)){var task=selected();if(task==null||!Confirmations.ask(this,text,task.name()+" · "+task.database()+"\n"+tr("¿Aplicar esta acción a la tarea seleccionada?")))return;}action.run();});bar.add(button);}
    private ScheduledTasks.Task selected(){int row=table.getSelectedRow();return row<0?null:tasks.get(table.convertRowIndexToModel(row));}
    private void refresh(){var before=selected();tasks=engine.list();model.setRowCount(0);for(var task:tasks){var state=engine.state(task.id());model.addRow(new Object[]{task.name(),tr(kind(task.kind())),task.database(),state.running()?tr("Ejecutando…"):tr(task.enabled()?"Sí":"No"),java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm").withZone(ZoneId.systemDefault()).format(task.next()),tr(state.status()),state.output()});}if(before!=null)for(int i=0;i<tasks.size();i++)if(tasks.get(i).id().equals(before.id())){int row=table.convertRowIndexToView(i);table.setRowSelectionInterval(row,row);}}
    private static String kind(ScheduledTasks.Kind kind){return switch(kind){case BACKUP->"Respaldo SQL";case REPORT->"Reporte SQL";case SQL->"Script SQL";};}
    private void edit(ScheduledTasks.Task previous,ScheduledTasks.Kind kind){
        if(previous!=null&&engine.state(previous.id()).running()){error(new IllegalStateException(tr("Espera a que termine la tarea.")));return;}List<ConnectionProfile> available=profiles.get();if(available.isEmpty()){error(new IllegalStateException(tr("Crea una conexión antes de programar tareas.")));return;}
        JComboBox<ConnectionProfile> connection=new JComboBox<>(available.toArray(ConnectionProfile[]::new));String profile=previous==null?defaultProfile:previous.profile();for(var p:available)if(p.id().equals(profile))connection.setSelectedItem(p);
        JTextField name=new JTextField(previous==null?tr(kind(kind)):previous.name()),base=new JTextField(previous==null?database:previous.database()),script=new JTextField(previous==null?"":previous.script()),output=new JTextField(previous==null?Path.of(System.getProperty("user.home"),"AdisDB-Reports").toString():previous.output());JPasswordField password=new JPasswordField();
        JSpinner start=new JSpinner(new SpinnerDateModel(Date.from(previous==null?Instant.now().plusSeconds(60):previous.next()),null,null,Calendar.MINUTE));start.setEditor(new JSpinner.DateEditor(start,"yyyy-MM-dd HH:mm"));JSpinner minutes=new JSpinner(new SpinnerNumberModel(previous==null?1440:previous.minutes(),0,525600,1));JCheckBox authorized=new JCheckBox(tr("Autorizo la ejecución automática de este script SQL en la conexión y base indicadas."));
        JPanel form=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;int row=0;field(form,g,row++,"Nombre:",name);field(form,g,row++,"Conexión:",connection);field(form,g,row++,"Base:",base);
        if(kind!=ScheduledTasks.Kind.BACKUP){JPanel file=new JPanel(new BorderLayout(6,0));file.add(script);JButton browse=new JButton("…");browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("SQL","sql"));if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)script.setText(chooser.getSelectedFile().toString());});file.add(browse,BorderLayout.EAST);field(form,g,row++,"Archivo SQL:",file);}
        JPanel folder=new JPanel(new BorderLayout(6,0));folder.add(output);JButton browse=new JButton("…");browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)output.setText(chooser.getSelectedFile().toString());});folder.add(browse,BorderLayout.EAST);field(form,g,row++,"Carpeta de salida:",folder);field(form,g,row++,"Primera ejecución:",start);field(form,g,row++,"Repetir cada (minutos; 0 = una vez):",minutes);field(form,g,row++,"Contraseña (solo esta sesión):",password);
        g.gridx=0;g.gridy=row++;g.gridwidth=2;form.add(new JLabel(tr("En Windows también puede utilizarse la contraseña cifrada guardada en el perfil.")),g);if(kind==ScheduledTasks.Kind.SQL){g.gridy=row++;form.add(authorized,g);g.gridy=row++;form.add(new JLabel(tr("Los cambios DDL pueden permanecer si una sentencia posterior falla.")),g);}form.setPreferredSize(new Dimension(800,kind==ScheduledTasks.Kind.SQL?430:360));
        if(JOptionPane.showConfirmDialog(this,form,tr("Programar tarea: ")+tr(kind(kind)),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;ConnectionProfile selected=(ConnectionProfile)connection.getSelectedItem();char[] secret=password.getPassword();
        if(kind==ScheduledTasks.Kind.SQL&&(!authorized.isSelected()||selected.readOnly())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("Autoriza el script y utiliza una conexión habilitada para escritura.")));return;}if(kind==ScheduledTasks.Kind.BACKUP&&!SqlBackupService.supported(selected.type())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("El respaldo SQL requiere MySQL o MariaDB.")));return;}
        String title=name.getText().trim(),target=base.getText().trim(),source=script.getText().trim(),destination=output.getText().trim();Instant date=((Date)start.getValue()).toInstant();int frequency=((Number)minutes.getValue()).intValue();
        new SwingWorker<SqlImportService.Analysis,Void>(){protected SqlImportService.Analysis doInBackground()throws Exception{return kind==ScheduledTasks.Kind.BACKUP?null:SqlImportService.analyze(Path.of(source),new SqlTransferControl());}protected void done(){try{var analysis=get();if(analysis!=null){JTextArea text=new JTextArea(selected.name()+" · "+selected.host()+":"+selected.port()+" · "+target+"\n"+analysis.statements()+" "+tr("sentencias")+" · "+analysis.destructive()+" "+tr("modifican o eliminan objetos/datos")+"\n\n"+analysis.preview(),15,80);text.setEditable(false);text.setCaretPosition(0);if(JOptionPane.showConfirmDialog(ScheduledTasksPanel.this,new JScrollPane(text),tr("Revisar el archivo antes de programar"),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;}
            if(!LicenseGate.ensure(ScheduledTasksPanel.this)||!Confirmations.ask(ScheduledTasksPanel.this,"Guardar tarea programada",title+"\n"+selected.name()+" · "+target+"\n"+date.atZone(ZoneId.systemDefault())+"\n"+tr("Se ejecutará automáticamente con las opciones revisadas mientras AdisDB esté abierto. ¿Programar?")))return;
            ScheduledTasks.Task task=new ScheduledTasks.Task(previous==null?UUID.randomUUID().toString():previous.id(),title,selected.id(),target,kind,analysis==null?"":analysis.file().toString(),analysis==null?"":analysis.sha256(),Path.of(destination).toAbsolutePath().toString(),frequency,date,true);engine.put(task);if(secret.length>0)engine.credentials(selected.id(),secret);refresh();
        }catch(Exception failure){error(failure.getCause()==null?failure:failure.getCause());}finally{Arrays.fill(secret,'\0');}}}.execute();
    }
    private static void field(JPanel form,GridBagConstraints g,int row,String caption,JComponent input){g.gridwidth=1;g.gridy=row;g.gridx=0;g.weightx=0;form.add(new JLabel(tr(caption)),g);g.gridx=1;g.weightx=1;form.add(input,g);}
    private void error(Throwable error){JOptionPane.showMessageDialog(this,error.getMessage(),tr("Tareas programadas"),JOptionPane.ERROR_MESSAGE);}
}
